INSERT INTO trick_definitions (discipline_slug, source_id, name, description, level) VALUES
  ('roller', 'soul', 'Soul', 'Lock the inside soul plate on the edge and slide centered to the exit.', 1),
  ('roller', 'acid', 'Acid', 'Lock the outside soul plate on the edge and ride the grind steady to the end.', 1),
  ('roller', 'pornstar', 'pornstar', 'Lock the front soul plate with the back foot topside and slide the full length balanced.', 1),
  ('roller', 'mizou', 'Mizou', 'Set the front frame groove across the edge and hold the mizou steady to the exit.', 1),
  ('roller', 'x-grind', 'X Grind', 'Cross the frames into an X and slide level and locked to the end.', 1),
  ('roller', 'makio', 'Makio', 'Set the back frame groove on the edge and ride the makio with weight centered.', 1),
  ('roller', 'royale', 'Royale', 'Lock both feet in the royale groove and grind the full length without splitting.', 1),
  ('roller', 'fahrver', 'Fahrver', 'Lock both feet in the royale groove on the far side and hold the farver to the end.', 1),
  ('roller', 'ufo', 'UFO', 'Cross into the UFO with both soul plates out and slide mirrored and balanced.', 1),
  ('roller', 'unity', 'Unity', 'Cross the feet into a tight unity and slide the full length before uncrossing.', 1),
  ('roller', 'savannah', 'Savannah', 'Lock the savannah with one foot soul and the other crossed behind, then slide low and steady.', 1),
  ('roller', 'mistrial', 'Mistrial', 'Lock the mistrial with legs crossed and opposite, and hold the slide to the end.', 1),
  ('roller', 'ao-makio', 'AO Makio', 'Approach switch and set the back groove into the AO makio, then ride it clean to the exit.', 1),
  ('roller', 'ao-mizou', 'AO Mizou', 'Approach switch and lock the front groove into the AO mizou, then slide steady to the end.', 1),
  ('roller', 'ao-soul', 'AO Soul', 'Approach switch and lock the inside soul plate into the AO soul, then slide centered out.', 1),
  ('roller', 'ao-acid', 'AO Acid', 'Approach switch and lock the outside soul plate into the AO acid, then ride to the exit.', 1),
  ('roller', '180', '180', 'Pop off the lip, rotate 180, and roll away clean.', 1),
  ('roller', '360', '360', 'Launch and spin a full 360, then stomp the landing rolling forward.', 1),
  ('roller', 'fakie-180', 'Fakie 180', 'Roll fakie, pop a 180, and ride away forward clean.', 1),
  ('roller', 'fakie-360', 'Fakie 360', 'Roll fakie, spin a full 360, and land rolling forward with control.', 1),
  ('roller', 'backside-ufo', 'Backside UFO', 'Approach backside and cross into the UFO, then grind the full length balanced.', 2),
  ('roller', 'top-soul', 'Top Soul', 'Lock the topside soul on top of the edge and slide the full length centered.', 2),
  ('roller', 'top-acid', 'Top Acid', 'Lock the topside acid on top of the edge and ride the grind steady to the end.', 2),
  ('roller', 'top-porn', 'Top Porn', 'Lock the top pornstar with the soul on top and the back foot braced, then slide clean.', 2),
  ('roller', 'sweatstance', 'Sweatstance', 'Lock the front royale and the back soul on top, then hold the sweatstance to the exit.', 2),
  ('roller', 'fishbrain', 'Fishbrain', 'Lock the front topside soul and the back royale, then hold the fishbrain steady to the end.', 2),
  ('roller', 'backslide', 'Backslide', 'Press the back soul plate on the edge and slide the full length with the frame aligned.', 2),
  ('roller', 'torque', 'Torque', 'Spin into the torque and lock the topside groove, then ride the full length steady.', 2),
  ('roller', 'backside-farver', 'Backside Farver', 'Approach backside and lock the farver groove on the edge, then grind to the end.', 2),
  ('roller', 'backside-royale', 'Backside Royale', 'Approach backside and lock both feet in the royale groove, then grind without splitting.', 2)
INSERT INTO trick_definitions (discipline_slug, source_id, name, description, level) VALUES
  ('roller', 'backside-unity', 'Backside Unity', 'Approach backside and cross the feet into the unity, then slide the full length.', 2),
  ('roller', 'backside-savannah', 'Backside Savannah', 'Approach backside and lock the savannah crossed behind, then slide low to the exit.', 2),
  ('roller', 'backside-torque', 'Backside Torque', 'Approach backside and spin into the torque groove, then hold the grind to the end.', 2),
  ('roller', 'true-makio', 'True Makio', 'Spin true into the back groove and hold the true makio centered to the exit.', 2),
  ('roller', 'true-mizou', 'True Mizou', 'Spin true into the front groove and hold the true mizou steady to the end.', 2),
  ('roller', 'true-soul', 'True Soul', 'Spin true into the inside soul plate and slide the full length centered.', 2),
  ('roller', 'true-acid', 'True Acid', 'Spin true into the outside soul plate and ride the true acid steady to the end.', 2),
  ('roller', 'kind-grind', 'Kind Grind', 'Spin true into the front groove with legs crossed and hold the kind grind to the exit.', 2),
  ('roller', 'ao-x-grind', 'AO X Grind', 'Approach switch and cross into the X-grind, then slide locked to the end.', 2),
  ('roller', '540', '540', 'Launch and spin 540 above the lip, then absorb the landing clean.', 2),
  ('roller', 'fakie-540', 'Fakie 540', 'Roll fakie, spin 540, and stomp the landing with control.', 2),
  ('roller', '720', '720', 'Launch and spin a full 720 above the transition, then stomp the landing clean.', 3),
  ('roller', 'fakie-720', 'Fakie 720', 'Roll fakie, spin a full 720, and land with knees soft and rolling.', 3),
  ('roller', 'ao-top-soul', 'AO Top Soul', 'Approach switch and lock the topside soul on top, then slide centered to the exit.', 3),
  ('roller', 'ao-fish', 'AO Fish', 'Approach switch and lock the fishbrain on top, then hold the slide steady to the end.', 3),
  ('roller', 'ao-top-acid', 'AO Top Acid', 'Approach switch and lock the topside acid on top, then ride the grind to the end.', 3),
  ('roller', 'true-top-porn', 'True Top Porn', 'Spin true into the top pornstar and slide the full length balanced.', 3),
  ('roller', 'true-top-acid', 'True Top Acid', 'Spin true into the topside acid and ride the top groove steady to the end.', 3),
  ('roller', 'true-fish', 'True Fish', 'Spin true into the fishbrain lock and hold the cross grind to the exit.', 3),
  ('roller', 'backflip', 'Backflip', 'Drive off the lip into a backflip and land with knees soft in the transition.', 3),
  ('roller', 'frontflip', 'Frontflip', 'Drive off the lip into a frontflip and absorb the landing clean.', 3)
INSERT INTO trick_definitions (discipline_slug, source_id, name, description, level) VALUES
  ('skateboard', 'ollie', 'Ollie', 'Pop the tail, slide the front foot up, and level the board to clear obstacles cleanly.', 1),
  ('skateboard', 'kickflip', 'Kickflip', 'Flick the front foot off the toe-side of the nose to spin the board a full flip and land bolts.', 1),
  ('skateboard', 'heelflip', 'Heelflip', 'Flick off the heel side of the nose and catch the board after a full rotation.', 1),
  ('skateboard', 'pop-shove-it', 'Pop Shove-It', 'Pop and scoop the tail backside to spin the board 180 degrees under your feet.', 1),
  ('skateboard', 'frontside-180', 'Frontside 180', 'Rotate a half turn frontside off the pop and roll away looking over the shoulder.', 1),
  ('skateboard', 'backside-180', 'Backside 180', 'Spin a half turn backside off the pop and ride away with the rotation tucked.', 1),
  ('skateboard', 'fakie-ollie', 'Fakie Ollie', 'Ollie while rolling backward and keep the pop crisp and the landing controlled.', 1),
  ('skateboard', 'manual', 'Manual', 'Balance on the back two wheels and ride the manual as long as you can without touching down.', 1),
  ('skateboard', 'no-comply', 'No Comply', 'Plant the front foot, pop the tail, and step back on in one smooth motion.', 1),
  ('skateboard', 'boneless', 'Boneless', 'Grab the board with the front hand, plant the front foot, and launch off the back leg.', 1),
  ('skateboard', '50-50-grind', '50-50 Grind', 'Ollie onto the obstacle, lock both trucks, and ride the grind to the end.', 1),
  ('skateboard', 'boardslide', 'Boardslide', 'Slide the deck flat across the obstacle with the trucks on either side of the edge.', 1),
  ('skateboard', 'noseslide', 'Noseslide', 'Balance on the nose and slide the front of the deck down the full ledge.', 1),
  ('skateboard', 'tailslide', 'Tailslide', 'Lock the tail end of the deck on the edge and slide it cleanly to the exit.', 1),
  ('skateboard', 'drop-in', 'Drop In', 'Stomp the nose over the coping and ride straight down the ramp with commitment.', 1),
  ('skateboard', 'kickturn', 'Kickturn', 'Lift the front wheels and pivot on the back wheels to turn around in the transition.', 1),
  ('skateboard', 'rock-to-fakie', 'Rock to Fakie', 'Roll up the wall, rock the board over the coping, and roll back in fakie.', 1),
  ('skateboard', 'axle-stall', 'Axle Stall', 'Pop onto the coping, balance on both axles, and roll back in without touching down.', 1),
  ('skateboard', 'tail-stall', 'Tail Stall', 'Stall with the tail on the coping and the board hanging off the edge before rolling in.', 1),
  ('skateboard', 'nose-grab', 'Nose Grab', 'Reach down and grab the nose mid-air, holding it through the arc of the air.', 1),
  ('skateboard', 'indy-grab', 'Indy Grab', 'Reach down and grab the middle of the board between the feet while airborne.', 1),
  ('skateboard', 'melon-grab', 'Melon Grab', 'Grab the heel-side edge of the deck and keep the air controlled from launch to landing.', 1),
  ('skateboard', 'mute-grab', 'Mute Grab', 'Reach across the front of the board and grab the toe-side edge mid-air.', 1),
  ('skateboard', 'nollie', 'Nollie', 'Pop the nose instead of the tail and slide the back foot forward to level the board.', 2),
  ('skateboard', 'switch-ollie', 'Switch Ollie', 'Ollie in your opposite stance with the pop and flick on the other side of the board.', 2),
  ('skateboard', 'nose-manual', 'Nose Manual', 'Balance on the front two wheels and ride the nose manual without touching the tail.', 2),
  ('skateboard', 'fakie-180', 'Fakie 180', 'Spin 180 out of fakie and roll away forward in one smooth motion.', 2),
  ('skateboard', 'half-cab', 'Half Cab', 'Fakie 180 backside into your natural stance and keep rolling without stopping.', 2),
  ('skateboard', 'nollie-kickflip', 'Nollie Kickflip', 'Pop the nose and flick the board into a kickflip from a nollie stance.', 2),
  ('skateboard', 'varial-flip', 'Varial Flip', 'Combine a 180 shove-it with a kickflip and land the rotation in one pop.', 2)
INSERT INTO trick_definitions (discipline_slug, source_id, name, description, level) VALUES
  ('skateboard', 'frontside-flip', 'Frontside Flip', 'Spin frontside 180 while flipping the board and catch it mid-turn.', 2),
  ('skateboard', 'bigspin', 'Bigspin', 'Scoop a 360 shove-it with a 180 body rotation and roll away clean.', 2),
  ('skateboard', '360-shove-it', '360 Shove-It', 'Scoop the tail hard to spin the board a full 360 without flipping.', 2),
  ('skateboard', '5-0-grind', 'Five-Oh Grind', 'Lock the back truck on the edge and balance the front wheels in the air through the grind.', 2),
  ('skateboard', 'nosegrind', 'Nosegrind', 'Lock the front truck on the obstacle and lift the tail to hold the grind line.', 2),
  ('skateboard', 'smith-grind', 'Smith Grind', 'Lock the back truck with the front truck tucked behind the far side of the obstacle.', 2),
  ('skateboard', 'feeble-grind', 'Feeble Grind', 'Lock the front truck with the back truck hanging on the far side of the rail.', 2),
  ('skateboard', 'crooked-grind', 'Crooked Grind', 'Lock the front truck and cross the tail over the obstacle at an angle for the full line.', 2),
  ('skateboard', 'lipslide', 'Lipslide', 'Approach backside and slide the tail-side edge of the deck across the obstacle.', 2),
  ('skateboard', 'frontside-boardslide', 'Frontside Boardslide', 'Approach frontside and slide the deck flat down the full length of the obstacle.', 2),
  ('skateboard', 'backside-boardslide', 'Backside Boardslide', 'Approach backside and ride the boardslide across the entire rail with control.', 2),
  ('skateboard', 'rock-n-roll', 'Rock n Roll', 'Rock over the coping and turn back in frontside instead of rolling to fakie.', 2),
  ('skateboard', 'disaster', 'Disaster', 'Pop into a 50-50 stall on the coping and pivot back in without touching down.', 2),
  ('skateboard', 'fakie-disaster', 'Fakie Disaster', 'Hit the coping in fakie, stall both trucks, and pivot back into the ramp.', 2),
  ('skateboard', 'nosebone', 'Nosebone', 'Grab the nose and stretch the board out with the tail pushed down mid-air.', 2),
  ('skateboard', 'stalefish-grab', 'Stalefish Grab', 'Reach behind the back leg and grab the heel-side edge of the board in the air.', 2),
  ('skateboard', 'method-air', 'Method Air', 'Grab the heel-side with the back hand and arch the board behind you mid-air.', 2),
  ('skateboard', 'invert', 'Invert', 'Plant a hand on the coping and hold the board inverted above the wall before dropping back in.', 2),
  ('skateboard', 'full-cab', 'Full Cab', 'Fakie 360 backside and land rolling forward in your natural stance.', 3),
  ('skateboard', 'switch-kickflip', 'Switch Kickflip', 'Kickflip in your opposite stance with the flick on the toe-side of the nose.', 3),
  ('skateboard', 'tre-flip', 'Tre Flip', 'Scoop a 360 shove-it while flipping the board a full rotation in the same pop.', 3),
  ('skateboard', 'hardflip', 'Hardflip', 'Flip the board frontside while spinning it a half shove-it off the front foot.', 3),
  ('skateboard', 'backside-flip', 'Backside Flip', 'Spin backside 180 while flipping the board and land the rotation tucked.', 3),
  ('skateboard', 'bigspin-flip', 'Bigspin Flip', 'Combine a 360 shove-it, a full flip, and a 180 body rotation in one motion.', 3),
  ('skateboard', 'dolphin-flip', 'Dolphin Flip', 'Flip the board nose over tail like a front flip and catch it clean at the top.', 3),
  ('skateboard', 'overcrook', 'Overcrook', 'Lock the front truck over the obstacle with the tail crossed through the rail line.', 3),
