  ('skateboard', 'kickflip-boardslide', 'Kickflip Boardslide', 'Flip the board and land the boardslide lock mid-rail with the deck flat.', 3)
INSERT INTO trick_definitions (discipline_slug, source_id, name, description, level) VALUES
  ('skateboard', '50-50-to-5-0', '50-50 to Five-Oh', 'Open the 50-50 into a five-oh mid-grind without breaking the slide.', 3),
