INSERT INTO trick_definitions (discipline_slug, source_id, name, description, level) VALUES
  ('bmx', 'bunny-hop', 'Bunny Hop', 'Hop the front wheel, then the rear, to clear obstacles and gaps cleanly.', 1),
  ('bmx', 'manual', 'Manual', 'Lift the front wheel and balance on the rear without pedaling for as long as you can.', 1),
  ('bmx', 'wheelie', 'Wheelie', 'Balance on the rear wheel while pedaling and ride it out with control.', 1),
  ('bmx', 'endo', 'Endo', 'Apply the front brake, lift the rear wheel, and hold the endo before rolling off.', 1),
  ('bmx', 'footjam', 'Footjam', 'Jam the front foot between the tire and fork to stop the bike and hold the pivot.', 1),
  ('bmx', 'fakie', 'Fakie', 'Ride backward after a half turn and roll away without touching a foot down.', 1),
  ('bmx', 'x-up', 'X-Up', 'Spin the bars 180 mid-air and snap them back before landing.', 1),
  ('bmx', 'barspin', 'Barspin', 'Spin the handlebars a full 360 while airborne and catch them clean.', 1),
  ('bmx', 'tabletop', 'Tabletop', 'Lay the bike flat over the obstacle mid-air and pull it back for the landing.', 1),
  ('bmx', 'one-footer', 'One Footer', 'Kick one foot off the pedal mid-air and bring it back before touching down.', 1),
  ('bmx', 'no-hander', 'No Hander', 'Take both hands off the bars mid-air and grab them again before landing.', 1),
  ('bmx', '180', '180', 'Spin a half turn with the bike and land rolling away in the opposite direction.', 1),
  ('bmx', 'drop-in', 'Drop In', 'Roll from the coping straight down the ramp and commit to the drop.', 1),
  ('bmx', 'kickturn', 'Kickturn', 'Lift the front wheel and pivot on the rear wheel to turn around in the transition.', 1),
  ('bmx', 'rock-to-fakie', 'Rock to Fakie', 'Ride up the wall, rock the front wheel over the coping, and roll back in fakie.', 1),
  ('bmx', 'double-peg-grind', 'Double Peg Grind', 'Lock both pegs on the obstacle and ride the grind all the way to the end.', 1),
  ('bmx', 'feeble-grind', 'Feeble Grind', 'Lock the front peg with the rear wheel dropping off the far side of the rail.', 1),
  ('bmx', 'tire-tap', 'Tire Tap', 'Ride up the ramp, tap the front tire on the coping, and roll back in fakie.', 1),
  ('bmx', '360', '360', 'Rotate a full 360 with the bike and stomp the landing facing the same direction.', 2),
  ('bmx', 'tailwhip', 'Tailwhip', 'Kick the rear of the bike around a full 360 under you and land with the rear wheel back.', 2),
