INSERT INTO challenge_catalog_tricks (catalog_id, source_id, name, description, level) VALUES
  ((SELECT id FROM challenge_catalogs WHERE discipline_slug = 'roller' AND source_sha256 = '63d0a55d669db6312354a8dc5dcdad3faa6a5beccccb4a4e6ed528321714b8b6'), 'soul', 'Soul', 'Lock the inside soul plate on the edge and slide centered to the exit.', 1),
  ((SELECT id FROM challenge_catalogs WHERE discipline_slug = 'roller' AND source_sha256 = '63d0a55d669db6312354a8dc5dcdad3faa6a5beccccb4a4e6ed528321714b8b6'), 'acid', 'Acid', 'Lock the outside soul plate on the edge and ride the grind steady to the end.', 1),
  ((SELECT id FROM challenge_catalogs WHERE discipline_slug = 'roller' AND source_sha256 = '63d0a55d669db6312354a8dc5dcdad3faa6a5beccccb4a4e6ed528321714b8b6'), 'pornstar', 'pornstar', 'Lock the front soul plate with the back foot topside and slide the full length balanced.', 1),
  ((SELECT id FROM challenge_catalogs WHERE discipline_slug = 'roller' AND source_sha256 = '63d0a55d669db6312354a8dc5dcdad3faa6a5beccccb4a4e6ed528321714b8b6'), 'mizou', 'Mizou', 'Set the front frame groove across the edge and hold the mizou steady to the exit.', 1),
  ((SELECT id FROM challenge_catalogs WHERE discipline_slug = 'roller' AND source_sha256 = '63d0a55d669db6312354a8dc5dcdad3faa6a5beccccb4a4e6ed528321714b8b6'), 'x-grind', 'X Grind', 'Cross the frames into an X and slide level and locked to the end.', 1),
  ((SELECT id FROM challenge_catalogs WHERE discipline_slug = 'roller' AND source_sha256 = '63d0a55d669db6312354a8dc5dcdad3faa6a5beccccb4a4e6ed528321714b8b6'), 'makio', 'Makio', 'Set the back frame groove on the edge and ride the makio with weight centered.', 1),
  ((SELECT id FROM challenge_catalogs WHERE discipline_slug = 'roller' AND source_sha256 = '63d0a55d669db6312354a8dc5dcdad3faa6a5beccccb4a4e6ed528321714b8b6'), 'royale', 'Royale', 'Lock both feet in the royale groove and grind the full length without splitting.', 1),
  ((SELECT id FROM challenge_catalogs WHERE discipline_slug = 'roller' AND source_sha256 = '63d0a55d669db6312354a8dc5dcdad3faa6a5beccccb4a4e6ed528321714b8b6'), 'fahrver', 'Fahrver', 'Lock both feet in the royale groove on the far side and hold the farver to the end.', 1),
  ((SELECT id FROM challenge_catalogs WHERE discipline_slug = 'roller' AND source_sha256 = '63d0a55d669db6312354a8dc5dcdad3faa6a5beccccb4a4e6ed528321714b8b6'), 'ufo', 'UFO', 'Cross into the UFO with both soul plates out and slide mirrored and balanced.', 1),
  ((SELECT id FROM challenge_catalogs WHERE discipline_slug = 'roller' AND source_sha256 = '63d0a55d669db6312354a8dc5dcdad3faa6a5beccccb4a4e6ed528321714b8b6'), 'unity', 'Unity', 'Cross the feet into a tight unity and slide the full length before uncrossing.', 1),
  ((SELECT id FROM challenge_catalogs WHERE discipline_slug = 'roller' AND source_sha256 = '63d0a55d669db6312354a8dc5dcdad3faa6a5beccccb4a4e6ed528321714b8b6'), 'savannah', 'Savannah', 'Lock the savannah with one foot soul and the other crossed behind, then slide low and steady.', 1),
  ((SELECT id FROM challenge_catalogs WHERE discipline_slug = 'roller' AND source_sha256 = '63d0a55d669db6312354a8dc5dcdad3faa6a5beccccb4a4e6ed528321714b8b6'), 'mistrial', 'Mistrial', 'Lock the mistrial with legs crossed and opposite, and hold the slide to the end.', 1),
  ((SELECT id FROM challenge_catalogs WHERE discipline_slug = 'roller' AND source_sha256 = '63d0a55d669db6312354a8dc5dcdad3faa6a5beccccb4a4e6ed528321714b8b6'), 'ao-makio', 'AO Makio', 'Approach switch and set the back groove into the AO makio, then ride it clean to the exit.', 1),
  ((SELECT id FROM challenge_catalogs WHERE discipline_slug = 'roller' AND source_sha256 = '63d0a55d669db6312354a8dc5dcdad3faa6a5beccccb4a4e6ed528321714b8b6'), 'ao-mizou', 'AO Mizou', 'Approach switch and lock the front groove into the AO mizou, then slide steady to the end.', 1),
  ((SELECT id FROM challenge_catalogs WHERE discipline_slug = 'roller' AND source_sha256 = '63d0a55d669db6312354a8dc5dcdad3faa6a5beccccb4a4e6ed528321714b8b6'), 'ao-soul', 'AO Soul', 'Approach switch and lock the inside soul plate into the AO soul, then slide centered out.', 1),
  ((SELECT id FROM challenge_catalogs WHERE discipline_slug = 'roller' AND source_sha256 = '63d0a55d669db6312354a8dc5dcdad3faa6a5beccccb4a4e6ed528321714b8b6'), 'ao-acid', 'AO Acid', 'Approach switch and lock the outside soul plate into the AO acid, then ride to the exit.', 1),
  ((SELECT id FROM challenge_catalogs WHERE discipline_slug = 'roller' AND source_sha256 = '63d0a55d669db6312354a8dc5dcdad3faa6a5beccccb4a4e6ed528321714b8b6'), '180', '180', 'Pop off the lip, rotate 180, and roll away clean.', 1),
  ((SELECT id FROM challenge_catalogs WHERE discipline_slug = 'roller' AND source_sha256 = '63d0a55d669db6312354a8dc5dcdad3faa6a5beccccb4a4e6ed528321714b8b6'), '360', '360', 'Launch and spin a full 360, then stomp the landing rolling forward.', 1),
